LONDON = [
    U2.T('c03', 'London (dispersion) forces, step by step', 53,
         'London forces (dispersion forces) are the **weakest** intermolecular forces, but they act between **all** molecules and atoms — and they are the **only** attraction between non-polar molecules and noble-gas atoms.',
         '**Step 1 — Electrons move.** In a non-polar molecule the electron cloud is evenly spread *on average*, but at any instant it may be a little more on one side.',
         '**Step 2 — Instantaneous dipole.** For that instant the molecule has a δ− side and a δ+ side.',
         '**Step 3 — Induced dipole.** That tiny dipole pushes or pulls the electrons of the neighbouring molecule, creating a dipole in it, lined up so that δ+ faces δ−.',
         '**Step 4 — Attraction.** The two short-lived dipoles attract. Millions of these flickering attractions together hold the molecules (Fig 2.10: two iodine molecules).',
         '**What makes them stronger?** (1) **More electrons / bigger molecules** — a large electron cloud is easily distorted (more polarisable). (2) **Larger contact area** — long, straight molecules touch more than compact, round ones.'),
    U2.SS('s02', 'Model: how a London force forms', 54, 'cm_london',
          [('a', 'Even cloud', 'Two non-polar molecules; on average the electrons are spread evenly — no dipole.'),
           ('b', 'Instant dipole', 'Electrons drift to one side of the left molecule: δ− on one side, δ+ on the other.'),
           ('c', 'Induced dipole', 'The δ+ end attracts the electrons of the right molecule → an induced dipole. δ+ … δ− attraction = London force.')],
          'Slide to see the three stages.'),
    U2.TB('t02', 'More electrons → stronger London forces → higher boiling point', 54,
          ['Substance', 'Electrons per molecule', 'Boiling point', 'State at 25 °C'],
          [['F₂', '18', '−188 °C', 'gas'], ['Cl₂', '34', '−34 °C', 'gas'], ['Br₂', '70', '59 °C', 'liquid'], ['I₂', '106', '184 °C', 'solid'],
           ['He', '2', '−269 °C', 'gas'], ['Ne', '10', '−246 °C', 'gas'], ['Ar', '18', '−186 °C', 'gas'], ['Xe', '54', '−108 °C', 'gas']],
          'Down a group the molecules get bigger, London forces get stronger, so boiling points rise.'),
    U2.TB('t03', 'The intermolecular forces compared', 58,
          ['Force', 'Acts between', 'Cause', 'Strength', 'Example'],
          [['London (dispersion)', 'all molecules; only force for non-polar ones', 'instantaneous and induced dipoles', 'weakest (grows with size)', 'I₂, CH₄, noble gases'],
           ['Dipole–dipole', 'polar molecules', 'permanent δ+ … δ−', 'stronger', 'HCl, SO₂'],
           ['Hydrogen bond', 'H on N, O or F … lone pair on N, O, F', 'very polar H–N, H–O, H–F', 'strongest of these', 'H₂O, NH₃, HF'],
           ['Ion–dipole', 'ions and polar molecules', 'ion charge … dipole', 'strong', 'NaCl dissolving in water']],
          'Order to remember: dispersion < dipole–dipole < hydrogen bond (textbook p.58).'),
    U2.MN('m01', 'Memory trick', 54, '**“Big clouds wobble more.”** More electrons → a bigger, softer cloud → easier to distort → stronger London forces → higher boiling point.'),
    U2.WK('w03', 'Worked example: why is I₂ a solid but Cl₂ a gas?', 54,
          'Chlorine is a gas and iodine a solid at room temperature, yet both are non-polar X₂ molecules. Explain.',
          ['Both molecules are non-polar, so the only forces between molecules are **London forces**.',
           'I₂ has 106 electrons; Cl₂ has 34. I₂ has the much larger electron cloud.',
           'A larger cloud is more easily distorted → bigger instantaneous dipoles → stronger London forces.',
           'More energy is needed to separate I₂ molecules → higher melting and boiling points → solid at 25 °C.'],
          'Stronger London forces between the larger I₂ molecules.'),
    U2.WK('w04', 'Worked example: HCl vs F₂', 53,
          'HCl (M = 36.5) boils at −85 °C; F₂ (M = 38) boils at −188 °C. Why the big difference for molecules of similar mass?',
          ['Similar mass and number of electrons → similar London forces.',
           'F₂ is non-polar: London forces only.',
           'HCl is polar: London forces **plus dipole–dipole** attractions.',
           'Extra attraction → more energy needed to boil → HCl has the higher boiling point.'],
          'HCl has dipole–dipole forces in addition to London forces.'),
    U2.CK('k03', 54, 'Which noble gas has the highest boiling point?', ['He', 'Ne', 'Ar', 'Xe'], 'D',
          'Xe has the most electrons → strongest London forces → highest boiling point.'),
    U2.CK('k04', 53, 'The only intermolecular force between CH₄ molecules is …',
          ['hydrogen bonding', 'dipole–dipole', 'London (dispersion) forces', 'ionic bonding'], 'C',
          'CH₄ is non-polar and has no H on N, O or F, so only London forces act.'),
    U2.RM('r01', 'Tips and common mistakes', 54,
          'Polar **bonds** ≠ polar **molecule**: always check the shape.',
          'London forces are present in **every** molecular substance — even polar ones. They are not “only for non-polar molecules”; they are just the *only* force there.',
          'Compare boiling points in this order: first check for hydrogen bonding, then polarity, then size (electrons).'),
]

