# ============================================================== Unit 4 Acids, bases and salts
U4 = Unit('chem10-u4')
L4 = '4.1 Acid–base theories'
DIAG4 = {'cm_acidbase': 'acidbase'}

THEORIES = [
    U4.T('c01', 'Arrhenius theory, step by step', 115,
         '**Acid:** a substance that produces **hydrogen ions, H⁺**, in water. **Base:** a substance that produces **hydroxide ions, OH⁻**, in water.',
         'HCl(aq) → H⁺(aq) + Cl⁻(aq); H₂SO₄(aq) → 2H⁺(aq) + SO₄²⁻(aq); NaOH(aq) → Na⁺(aq) + OH⁻(aq).',
         '**Neutralisation** is then simply H⁺(aq) + OH⁻(aq) → H₂O(l).',
         '**Limitations:** (1) it works only in **water**; (2) it cannot explain why **ammonia, NH₃**, is a base — NH₃ contains no OH; (3) a bare H⁺ does not exist in water — it is attached to a water molecule as **H₃O⁺** (hydronium ion).'),
    U4.T('c02', 'Brønsted–Lowry theory, step by step', 115,
         '**Acid = proton (H⁺) donor. Base = proton (H⁺) acceptor.** An acid–base reaction is a **proton transfer**.',
         '**Step 1 — Find which particle loses an H⁺.** That is the acid. HCl + H₂O → H₃O⁺ + Cl⁻: HCl loses H⁺ → acid; H₂O gains it → base.',
         '**Step 2 — Find the conjugate pairs.** When an acid loses H⁺ it becomes its **conjugate base** (HCl → Cl⁻). When a base gains H⁺ it becomes its **conjugate acid** (H₂O → H₃O⁺). The two members of a pair differ by **exactly one H⁺**.',
         '**Step 3 — Ammonia now makes sense:** NH₃ + H₂O ⇌ NH₄⁺ + OH⁻. NH₃ accepts H⁺ → base; H₂O donates H⁺ → acid.',
         '**Amphiprotic (amphoteric) species** can act as acid or base: H₂O, HCO₃⁻, HSO₄⁻, H₂PO₄⁻.',
         '**Strength rule:** the stronger the acid, the weaker its conjugate base (HCl is strong, Cl⁻ has almost no tendency to take H⁺ back).'),
    U4.T('c03', 'Lewis theory, step by step (extension)', 115,
         'The textbook covers Arrhenius and Brønsted–Lowry. The **Lewis** theory is the broadest and is met again in Grade 12 and university entrance questions:',
         '**Lewis acid = electron-pair acceptor. Lewis base = electron-pair donor.** The product has a new **coordinate (dative) bond**.',
         '**Step 1 — Look for a lone pair.** The particle that gives the lone pair is the base (NH₃, H₂O, OH⁻, F⁻, Cl⁻).',
         '**Step 2 — Look for an empty orbital.** The particle that receives the pair is the acid (H⁺, BF₃, AlCl₃, metal ions such as Ag⁺, Cu²⁺, Fe³⁺).',
         '**Example:** BF₃ + :NH₃ → F₃B←NH₃. BF₃ has only 6 electrons around B, so it accepts the pair; there is no proton at all, so only the Lewis theory calls this an acid–base reaction.',
         'Every Brønsted base is also a Lewis base (it needs a lone pair to take an H⁺), and H⁺ itself is a Lewis acid.'),
    U4.ST('s01', 'Model: the three theories side by side', 115, 'cm_acidbase',
          [('**Arrhenius** — in water: acids give H⁺, bases give OH⁻.', 'ar'),
           ('**Brønsted–Lowry** — the acid gives a proton to the base: HCl + H₂O → H₃O⁺ + Cl⁻.', 'bl'),
           ('**Lewis** — the base gives an electron pair to the acid: NH₃ → BF₃.', 'lw')],
          'Each theory includes everything the one before it explained, and more.'),
    U4.TB('t01', 'Comparison of the three theories', 115,
          ['Theory', 'Acid', 'Base', 'Example', 'Scope / limitation'],
          [['Arrhenius', 'gives H⁺ in water', 'gives OH⁻ in water', 'HCl → H⁺ + Cl⁻; NaOH → Na⁺ + OH⁻', 'water only; cannot explain NH₃'],
           ['Brønsted–Lowry', 'proton (H⁺) donor', 'proton acceptor', 'NH₃ + H₂O ⇌ NH₄⁺ + OH⁻', 'any solvent or gas; needs a proton'],
           ['Lewis (extension)', 'electron-pair acceptor', 'electron-pair donor', 'BF₃ + NH₃ → F₃B–NH₃', 'broadest; no H⁺ needed']]),
    U4.TB('t02', 'Conjugate acid–base pairs (differ by one H⁺)', 116,
          ['Acid', 'Conjugate base', 'Base', 'Conjugate acid'],
          [['HCl', 'Cl⁻', 'H₂O', 'H₃O⁺'], ['H₂SO₄', 'HSO₄⁻', 'NH₃', 'NH₄⁺'], ['HSO₄⁻', 'SO₄²⁻', 'OH⁻', 'H₂O'],
           ['CH₃COOH', 'CH₃COO⁻', 'CO₃²⁻', 'HCO₃⁻'], ['H₂CO₃', 'HCO₃⁻', 'HCO₃⁻', 'H₂CO₃'], ['NH₄⁺', 'NH₃', 'CH₃COO⁻', 'CH₃COOH']],
          'Conjugate base: remove one H and lower the charge by 1. Conjugate acid: add one H and raise the charge by 1.'),
    U4.MN('m01', 'Memory trick: A–B–L', 115, 'Match the first letters:',
          [('A', 'Arrhenius', '**A**queous: H⁺ and OH⁻ in water'), ('B', 'Brønsted–Lowry', '**B**are proton passed from acid to base'), ('L', 'Lewis', '**L**one pair given by the base')]),
    U4.WK('w01', 'Worked example: ammonia in water', 124,
          'For NH₃(aq) + H₂O(l) ⇌ NH₄⁺(aq) + OH⁻(aq), identify the Brønsted acid, base and the two conjugate pairs.',
          ['H₂O loses an H⁺ and becomes OH⁻ → H₂O is the **acid**, OH⁻ its **conjugate base**.',
           'NH₃ gains an H⁺ and becomes NH₄⁺ → NH₃ is the **base**, NH₄⁺ its **conjugate acid**.',
           'Pairs: H₂O/OH⁻ and NH₄⁺/NH₃. Each pair differs by one H⁺.',
           'Arrhenius could not call NH₃ a base (it has no OH); Brønsted–Lowry can.'],
          'Acid H₂O, base NH₃; pairs H₂O/OH⁻ and NH₄⁺/NH₃.'),
    U4.WK('w02', 'Worked example: HCO₃⁻ is amphiprotic', 116,
          'Show with equations that the hydrogen carbonate ion, HCO₃⁻, can act as both a Brønsted acid and a Brønsted base.',
          ['As an **acid** (with OH⁻): HCO₃⁻ + OH⁻ → CO₃²⁻ + H₂O — it donates H⁺; conjugate base CO₃²⁻.',
           'As a **base** (with H₃O⁺): HCO₃⁻ + H₃O⁺ → H₂CO₃ + H₂O — it accepts H⁺; conjugate acid H₂CO₃.',
           'A species that can both donate and accept H⁺ is **amphiprotic**.'],
          'HCO₃⁻ donates H⁺ to OH⁻ and accepts H⁺ from H₃O⁺.'),
    U4.WK('w03', 'Worked example: which theory fits?', 115,
          'Classify each reaction as acid–base under Arrhenius, Brønsted–Lowry and/or Lewis: (a) HCl(aq) + NaOH(aq) → NaCl(aq) + H₂O(l); (b) HCl(g) + NH₃(g) → NH₄Cl(s); (c) BF₃ + F⁻ → BF₄⁻.',
          ['(a) In water, HCl gives H⁺ and NaOH gives OH⁻ → **Arrhenius**; H⁺ is transferred → **Brønsted**; OH⁻ gives a lone pair to H⁺ → **Lewis**. All three.',
           '(b) No water, so not Arrhenius. HCl gives H⁺ to NH₃ → **Brønsted** (and Lewis).',
           '(c) No proton is transferred. F⁻ donates an electron pair to BF₃ → **Lewis only**.'],
          '(a) all three; (b) Brønsted–Lowry and Lewis; (c) Lewis only.'),
    U4.CK('k01', 116, 'What is the conjugate base of H₂SO₄?', ['SO₄²⁻', 'HSO₄⁻', 'H₃SO₄⁺', 'H₂O'], 'B',
          'Remove one H⁺: H₂SO₄ → HSO₄⁻ (charge goes from 0 to −1).'),
    U4.CK('k02', 116, 'What is the conjugate acid of NH₃?', ['NH₂⁻', 'NH₄⁺', 'N₂', 'NH₃⁺'], 'B',
          'Add one H⁺: NH₃ → NH₄⁺.'),
    U4.CK('k03', 115, 'Why does the Arrhenius theory fail for ammonia?',
          ['NH₃ is not soluble', 'NH₃ contains no OH⁻ but still makes a solution basic', 'NH₃ is an acid', 'NH₃ has no hydrogen'], 'B',
          'Arrhenius bases must contain and release OH⁻. NH₃ makes OH⁻ by taking H⁺ from water — explained by Brønsted–Lowry.'),
    U4.CK('k04', 115, 'In BF₃ + NH₃ → F₃B–NH₃, BF₃ acts as a …',
          ['Brønsted acid', 'Lewis acid', 'Lewis base', 'Arrhenius base'], 'B',
          'BF₃ accepts the lone pair of NH₃ → Lewis acid. No proton is involved, so Brønsted does not apply.'),
    U4.RM('r01', 'Tips and common mistakes', 116,
          'A conjugate pair differs by **one** H⁺ only: H₂SO₄/SO₄²⁻ is **not** a pair.',
          'Water can be an acid (with NH₃) or a base (with HCl) — always decide from the reaction.',
          'In exam answers write H₃O⁺ (hydronium) rather than a bare H⁺ when water is involved.'),
]

